INSERT INTO grammar_lessons (id, grammar_chapter_id, title, pattern, meaning_vi, explanation, formation, jlpt_level_id, display_order, is_published, version) VALUES
(1, 1, 'Câu khẳng định:', 'S: Chủ ngữ (わたし、ヤマダさん、ちち、はは、あのひ / と、。。。)', 'Câu khẳng định:', 'Tôi là Samurai. Tôi là giáo viên. Tôi là người Việt Nam. Tôi 18 tuổi. 1. CÂU KHẲNG ĐỊNH 2. CÂU PHỦ ĐỊNH 3. CÂU NGHI VẤN • Hỏi tuổi:', 'S: Chủ ngữ (わたし、ヤマダさん、ちち、はは、あのひ / と、。。。) / N: Tên, nghề nghiệp, quốc tịch (～じん), tuổi (～さい)。。。', 1, 1, TRUE, 1),
(2, 1, 'Câu phủ định:', 'Câu phủ định:', 'Câu phủ định:', 'Tôi không phải là bác sĩ.', 'わたし は いしゃ じゃありません。', 1, 2, TRUE, 1),
(3, 1, 'Câu nghi vấn:', 'Câu nghi vấn:', 'Câu nghi vấn:', 'N N • Từ để hỏi:', 'Q：ミンさんは がくせいですか。 / A： / はい、がくせい です。', 1, 3, TRUE, 1),
(4, 1, 'Trợ từ の：', 'Trợ từ の：', 'Trợ từ の：', 'Ý nghĩa: N2 của N1', '4. Trợ từ の： / サムライにほんご の がくせい。 / わたしは ハノイだいがくの がくせいです。', 1, 4, TRUE, 1),
(5, 1, 'Trợ từ も:', 'S は từ để hỏi / N1 の N2', 'Trợ từ も:', 'Ý nghĩa: A là N. B cũng là N.', '5. Trợ từ も: / S は từ để hỏi / ですか。', 1, 5, TRUE, 1),
(6, 2, 'Cái này/ đó/ kia:', '➢ これ：Dùng để chỉ vật ở gần người nói, xa người nghe. / ➢ それ：Dùng để chỉ vật ở gần người nghe, xa người nói.', 'Cái này/ đó/ kia:', 'Cách dùng:', '➢ これ：Dùng để chỉ vật ở gần người nói, xa người nghe. / ➢ それ：Dùng để chỉ vật ở gần người nghe, xa người nói. / ➢ あれ：Dùng để chỉ vật ở xa 2 người.', 1, 1, TRUE, 1),
(7, 2, '～ Này/ Đó/ Kia:', '➢ Nhấn mạnh vào đối tượng trước mắt. / ➢ Về tương quan khoảng cách, giống với これ／それ／あれ.', '～ Này/ Đó/ Kia:', 'Cách dùng: ➢ Nhấn mạnh vào đối tượng trước mắt. Lưu ý:', '2. ～ Này/ Đó/ Kia: / ➢ Nhấn mạnh vào đối tượng trước mắt. / ➢ Về tương quan khoảng cách, giống với これ／それ／あれ.', 1, 2, TRUE, 1),
(8, 2, 'そうです: Đúng vậy, đúng rồi', 'そうです: Đúng vậy, đúng rồi / ちがいます: Không phải, sai rồi', 'そうです: Đúng vậy, đúng rồi', 'A： VD:', 'そうです: Đúng vậy, đúng rồi / ちがいます: Không phải, sai rồi / Q：これ／それ／あれ', 1, 3, TRUE, 1),
(9, 2, 'Là N1 hay là N2:', 'N1 / の N2', 'Là N1 hay là N2:', 'Cách dùng: ➢ Là câu hỏi lựa chọn. ➢ Dùng khi phân vân, không biết rõ đối tượng là ai (cái gì). N1 (người) (đồ vật) Lưu ý:', '4. Là N1 hay là N2: / N1 / の N2', 1, 4, TRUE, 1),
(10, 2, 'N2 của N1:', 'N2 đôi khi được lược bỏ khi đã được nhắc đến trước đó hay đã', 'N2 của N1:', 'Cách dùng: Dùng để miêu tả 1 món đồ thuộc quyền sở hữu của ai đó. Lưu ý: N2 đôi khi được lược bỏ khi đã được nhắc đến trước đó hay đã rõ nghĩa.', '5. N2 của N1: / N2 đôi khi được lược bỏ khi đã được nhắc đến trước đó hay đã / これは わたしの チョコレートです。', 1, 5, TRUE, 1),
(11, 2, 'Cái này/ Đó/ Kia là ∼ về ∼', '➢ Trợ từ の: thuộc về.', 'Cái này/ Đó/ Kia là ∼ về ∼', 'Cách dùng: ➢ Dùng khi muốn nói về thuộc tính của đồ vật: lĩnh vực, chuyên ngành,…', '➢ Trợ từ の: thuộc về. / これは えいごの じしょです。 / Q:このN／その N／あの N はだれの ですか。', 1, 6, TRUE, 1),
(12, 3, 'Chỗ này/ đó/ kia là N:', 'Chỗ này/ đó/ kia là N: / ここ', 'Chỗ này/ đó/ kia là N:', 'Chú ý:', 'Chỗ này/ đó/ kia là N: / ここ / そこ は N です。', 1, 1, TRUE, 1),
(13, 3, 'S là ở N:', 'S: người, vật, địa điểm. / N: địa điểm.', 'S là ở N:', 'Cách dùng: S: người, vật, địa điểm. N: địa điểm. Nhấn mạnh chủ ngữ đang ở địa điểm N.', '2. S là ở N: / S は N です。 / S: người, vật, địa điểm.', 1, 2, TRUE, 1),
(14, 3, 'N là ở đâu?', 'N là ở đâu?', 'N là ở đâu?', 'Cô Linh ở đâu? Cô Linh ở trong phòng học. • Cách nói trang trọng hơn:', '3. N là ở đâu? / Q： N は どこですか。 / A： Địa điểm です。', 1, 3, TRUE, 1),
(15, 3, 'Hỏi tên nước, công ty, trường học：', 'かいしゃ', 'Hỏi tên nước, công ty, trường học：', 'Bạn đến từ quốc gia nào? Tôi đến từ Việt Nam.', 'A： おくに / だいがく は どちらですか。 / かいしゃ', 1, 4, TRUE, 1),
(16, 3, 'Trợ từ の (xuất xứ):', 'これ / あれ', 'Trợ từ の (xuất xứ):', 'Đây là giày Nhật.', '5. Trợ từ の (xuất xứ): / これ / それ は nơi sản xuất の N です。', 1, 5, TRUE, 1),
(17, 3, 'Giá tiền của đồ vật:', 'この / あの', 'Giá tiền của đồ vật:', 'Chiếc đồng hồ này có giá 600 Yên.', 'この / その N は ～えん・ドル・ドンです。 / あの', 1, 6, TRUE, 1),
(18, 4, 'Bây giờ là ～ giờ ～ phút:', 'いま、～時 / じ', 'Bây giờ là ～ giờ ～ phút:', 'Cách dùng: ：chỉ số giờ • Số đếm + ：chỉ số phút ：chỉ giờ rưỡi Lưu ý: Để phân biệt thời gian buổi sáng, chiều, hay tối, người ta thêm', 'いま、～時 / じ / ～分', 1, 1, TRUE, 1),
(19, 4, 'Là thứ mấy?:', 'Là thứ mấy?:', 'Là thứ mấy?:', 'Hôm nay là thứ mấy? Hôm nay là thứ 5.', 'Q: ～は なんようびですか。 / A：～ようびです。 / Q: きょうは なんようびですか。', 1, 2, TRUE, 1),
(20, 4, 'Động từ ます:', '✓ Động từ là loại từ kết thúc bằng ます. / おきます', 'Động từ ます:', 'Tôi học bài mỗi tối. Chú ý:', '3. Động từ ます: / ✓ Động từ là loại từ kết thúc bằng ます. / おきます', 1, 3, TRUE, 1),
(21, 4, 'Làm V vào lúc ～ giờ：', 'ねます / ねません', 'Làm V vào lúc ～ giờ：', 'Hôm qua tôi đã ngủ lúc 10 giờ tối.', '4. Làm V vào lúc ～ giờ： / ねます / ねません', 1, 4, TRUE, 1),
(22, 4, 'Từ ～ đến :', 'N1, N2: thời gian, địa điểm. / ➢ から：biểu thị điểm bắt đầu.', 'Từ ～ đến :', 'Ý nghĩa: ➢ Là cách nói khoảng thời gian từ lúc nào đến lúc nào, từ đâu đến đâu.', 'です。 / V ます。 / N1, N2: thời gian, địa điểm.', 1, 5, TRUE, 1),
(23, 4, 'N1 và N2:', 'N1 と N2', 'N1 và N2:', 'Cách dùng: ➢ Ý nghĩa: với, và, cùng. ➢ Dùng để nối danh từ với danh từ.', '6. N1 và N2: / N1 と N2 / このびじゅつかんは きんようびと どようび やすみます。', 1, 6, TRUE, 1),
(24, 5, 'Nói ngày, tháng, năm:', 'Nói ngày, tháng, năm:', 'Nói ngày, tháng, năm:', 'Hôm nay là ngày mùng 1 tháng 4.', 'Nói ngày, tháng, năm: / Thời gian は ～ねん～がつ～にちです。 / Thời gian: きょう、～のたんじょうび、あした、。。。', 1, 1, TRUE, 1),
(25, 5, 'Động từ chuyển động:', 'S は N へ いきます (đi) / きます (đến)', 'Động từ chuyển động:', 'Ý nghĩa: Đi, đến, về một địa điểm nào đó. Chú ý: Trợ từ へ dùng để chỉ phương hướng di chuyển.', '1. NGÀY, THÁNG, NĂM 4. TRỢ TỪ で / 2. ĐỘNG TỪ CHUYỂN ĐỘNG H 5. TRỢ TỪ と / 3. ĐI/ ĐẾN/ VỀ ĐÂU', 1, 2, TRUE, 1),
(26, 5, 'Hỏi đi/ đến/ về đâu?:', 'Hỏi đi/ đến/ về đâu?:', 'Hỏi đi/ đến/ về đâu?:', 'Tháng 7 này cậu đi đâu không? Tớ đi Đà Nẵng', 'Q: どこへ いきますか。 / A： Địa điểm へ いきます。 / どこも いきません。', 1, 3, TRUE, 1),
(27, 5, 'Bằng phương tiện gì 「で」：', 'S は N で N へ いきます / (phương tiện) (địa điểm) きます', 'Bằng phương tiện gì 「で」：', 'Tôi đến siêu thị bằng xe đạp. • Hỏi đi bằng phương tiện gì?', '4. Bằng phương tiện gì 「で」： / S は N で N へ いきます / (phương tiện) (địa điểm) きます', 1, 4, TRUE, 1),
(28, 5, 'Làm gì với ai đó 「と」：', 'Làm gì với ai đó 「と」：', 'Làm gì với ai đó 「と」：', 'Mẫu ngữ pháp N5: Làm gì với ai đó 「と」：.', '5. Làm gì với ai đó 「と」： / S は N と N へ いきます。 / (người) (địa điểm) きます。', 1, 5, TRUE, 1),
(29, 6, 'Ăn ～, uống ～, làm ～：', '➢ N: Danh từ (đối tượng của hành động V). / ➢ V: Tha động từ (những động từ có sự tác động trực tiếp của', 'Ăn ～, uống ～, làm ～：', 'Cách dùng: ➢ N: Danh từ (đối tượng của hành động V). ➢ V: Tha động từ (những động từ có sự tác động trực tiếp của con người).', 'N を V ます。 / ➢ N: Danh từ (đối tượng của hành động V). / ➢ V: Tha động từ (những động từ có sự tác động trực tiếp của', 1, 1, TRUE, 1),
(30, 6, 'Làm, chơi, tổ chức:', 'Làm, chơi, tổ chức:', 'Làm, chơi, tổ chức:', 'Cuối tuần tớ sẽ chơi tennis. • Làm (đã làm) gì? Cách dùng: ➢ Đây là mẫu câu hỏi chung cho tất cả các động từ. ➢ Nếu không làm gì thì sẽ trả lời:', 'N を します。 / しゅうまつ テニスを します。 / Q：なにを しますか／しましたか。', 1, 2, TRUE, 1),
(31, 6, '～Làm (đã làm) cái gì ở đâu?:', '～Làm (đã làm) cái gì ở đâu?:', '～Làm (đã làm) cái gì ở đâu?:', 'Cậu ăn trưa ở đâu? Tớ ăn trưa ở nhà ăn.', 'Q: どこで N を しますか／しましたか。 / A：Địa điểm で (N を） V ます／ました。 / Q: どこで ひるごはんを たべますか。', 1, 3, TRUE, 1),
(32, 6, 'Cùng ～ với mình chứ?', '➢ ええ、いいですね: Vâng, hay nhỉ (được đấy nhỉ). / ➢ すみません、ちょっと。。。: Xin lỗi, nhưng mà….', 'Cùng ～ với mình chứ?', 'Cách dùng: ➢ Dùng để mời, đề nghị ai đó cùng làm việc gì đó với mình. (Đây là cách từ chối khéo lời mời)', 'Q：いっしょに V ませんか。 / A： ええ、いいですね。 / すみません、ちょっと。。。', 1, 4, TRUE, 1),
(33, 6, 'Cùng làm ～nhé：', '➢ 「ませんか」： / ➢ 「ましょう」：', 'Cùng làm ～nhé：', 'Cách dùng: ➢ Mời, đề nghị ai đó làm gì cùng mình, thể hiện thái độ chủ động của người nói. ➢ Hô hào mọi người cùng làm gì đó. ✓ Sử dụng khi chưa biết người nghe có đồng ý với lời mời, đề nghị hay là không. ✓ Thể hiện thái độ rụt rè, giữ ý của người nói. ✓ Sử dụng khi đã biết người nghe đã đồng ý với lời mời, đề nghị của mình. ✓ Mẫu câu này cũng được dùng để trả lời cho mẫu', 'N を ましょう。 / • Phân biệt 「ませんか」 và「ましょう」。 / ➢ 「ませんか」：', 1, 5, TRUE, 1),
(34, 7, 'Dùng phương tiện, cách thức nào đó để ~ ：', 'Dùng phương tiện, cách thức nào đó để ~ ：', 'Dùng phương tiện, cách thức nào đó để ~ ：', 'Cắt giấy bằng kéo. • Làm V bằng phương tiện, công cụ nào?', 'N で Ｎを V ます。 / はさみで かみを きります。 / • Làm V bằng phương tiện, công cụ nào?', 1, 1, TRUE, 1),
(35, 7, 'A trong ngôn ngữ nào đó là B:', 'A trong ngôn ngữ nào đó là B: / Chú ý: A , B có thể là 1 câu, 1 từ ngữ hoặc 1 đại từ chỉ thẳng.', 'A trong ngôn ngữ nào đó là B:', 'Chú ý: A , B có thể là 1 câu, 1 từ ngữ hoặc 1 đại từ chỉ thẳng.', 'A trong ngôn ngữ nào đó là B: / Ａは ～ごで Ｂです。 / ほん', 1, 2, TRUE, 1),
(36, 7, 'Câu cho nhận 1 N:', 'người cho người nhận V cho / ➢ A cho B 1 N nào đó.', 'Câu cho nhận 1 N:', 'Ý nghĩa: ➢ A cho B 1 N nào đó. ➢ V cho:', '3. Câu cho nhận 1 N: / A は B に Ｎを Ｖます。 / người cho người nhận V cho', 1, 3, TRUE, 1),
(37, 7, 'Đã làm xong V rồi:', 'Đã làm xong V rồi:', 'Đã làm xong V rồi:', 'Tôi đã ăn sáng rồi. • Đã làm V chưa?', 'Đã làm xong V rồi: / Ｓは もう Ｎを Ｖました。 / わたしは もう あさごはんを たべました。', 1, 4, TRUE, 1),
(38, 8, 'Tính từ:', '• Tính từ đuôi い：', 'Tính từ:', 'Tính từ:', '• Tính từ đuôi い： / つめたい (lạnh)、やすい (rẻ)、たかい(cao/ đắt)、。。。 / Tính từ đuôi な：', 1, 1, TRUE, 1),
(39, 8, 'Câu khẳng định của tính từ:', '➢ N thì ∼ / ➢ Ở mẫu câu này, nếu tính từ đuôi いthì giữ nguyên い, tính từ', 'Câu khẳng định của tính từ:', 'Ý nghĩa: ➢ N thì ∼', 'N は A い／ A なです。 / 1. TÍNH TỪ. / 2. CÂU KHẲNG ĐỊNH CỦA TÍNH TỪ.', 1, 2, TRUE, 1),
(40, 8, 'Câu phủ định của tính từ:', '➢ N thì không∼ / 「いい」→ 「よくない」', 'Câu phủ định của tính từ:', 'Ý nghĩa: ➢ N thì không∼ ➢ Trường hợp phủ định của tính từ:', 'Ｎは A い くないです。 / A な じゃ（では）ありません。 / ➢ N thì không∼', 1, 3, TRUE, 1),
(41, 8, 'Tính từ bổ nghĩa cho danh từ:', 'A いN2', 'Tính từ bổ nghĩa cho danh từ:', 'Cách dùng: ➢ Khi tính từ bổ nghĩa cho danh từ, cả cụm tính từ + danh từ đó được coi như 1 danh từ. Vì thế, khi chia phủ định, quá khứ thì chia như 1 danh từ.', 'N1 は A な N2 です。 / A いN2', 1, 4, TRUE, 1),
