(84, 17, 'Phải làm V, bắt buộc phải làm V:', 'Phải làm V, bắt buộc phải làm V:', 'Phải làm V, bắt buộc phải làm V:', 'Cách dùng: Khi một việc coi như nghĩa vụ phải làm, bất chấp ý hướng của người làm. Chú ý: Mặc dù động từ chia ở dạng phủ định nhưng cả câu không mang nghĩa phủ định.', 'Phải làm V, bắt buộc phải làm V: / V なければ なりません。 / V ない + ければ なりません。', 1, 2, TRUE, 1),
(85, 17, 'Không cần làm V cũng được:', 'Không cần làm V cũng được:', 'Không cần làm V cũng được:', 'Không cần trả tiền cũng được.', 'Không cần làm V cũng được: / V なくてもいいです。 / V ない + くて もいいです。', 1, 3, TRUE, 1),
(86, 17, 'Chậm nhất, cho đến trước khi:', 'N までに', 'Chậm nhất, cho đến trước khi:', 'Cách dùng: Chỉ rõ thời gian cuối mà một hành động hay một công việc phải được tiến hành trước thời hạn được chỉ định.', 'N までに / 金曜日 / きんようび', 1, 4, TRUE, 1),
(87, 17, 'Nhấn mạnh N:', 'Nhấn mạnh N: / ～N を V ます', 'Nhấn mạnh N:', 'Cách dùng: Ø Đưa tân ngữ lên làm chủ ngữ để nhằm nhấn mạnh ý muốn diễn tả.', 'Nhấn mạnh N: / ～N を V ます / N は～ V ます', 1, 5, TRUE, 1),
(88, 18, 'Có thể/ có khả năng:', 'Ｖ(từ điển) ＝ Ｖます / ～i ます → ～u', 'Có thể/ có khả năng:', '1. CÓ THỂ/ CÓ KHẢ NĂNG. 2. SỞ THÍCH. 3. TRƯỚC (KHI). 4. MÃI MÀ KHÔNG. 5. RẤT MUỐN ～/ NHẤT ĐỊNH HÃY ～. Ø Động từ nhóm II:', 'Ｖ(từ điển) ＝ Ｖます / ～i ます → ～u / あいます(gặp) → あう', 1, 1, TRUE, 1),
(89, 18, 'Sở thích:', 'V ること', 'Sở thích:', 'Sở thích của tôi là du lịch. • Sở thích của bạn là gì?', '（わたしの）しゅみは N です。 / V ること / しゅみは なんですか。', 1, 2, TRUE, 1),
(90, 18, 'Trước khi làm ～ thì làm V2 :', 'V1 る まえに、V2 / N の', 'Trước khi làm ～ thì làm V2 :', 'Chú ý: Ø Thì của câu được biểu thị ở V2.', 'V1 る まえに、V2 / N の / Ø N là danh từ chỉ hành động, hành vi: りょこう(du lịch)、', 1, 3, TRUE, 1),
(91, 18, 'Mãi mà không:', 'Mãi mà không:', 'Mãi mà không:', 'Chú ý: Luôn đi kèm với động từ phủ định.', 'なかなか V ません。 / わたしは 日本語 / にほんご', 1, 4, TRUE, 1),
(92, 18, 'Rất muốn ～ nhất định hãy ～:', 'Rất muốn ～ nhất định hãy ～:', 'Rất muốn ～ nhất định hãy ～:', 'Tôi rất muốn leo núi Phú Sĩ.', 'ぜひ、 V たいです。 / ぜひ、 V てください。 / ぜひ、ふじさんに のぼりたいです。', 1, 5, TRUE, 1),
(93, 19, 'Đã từng làm V:', 'Đã từng làm V: / • Thể た：', 'Đã từng làm V:', 'Ø Động từ nhóm II:', 'Đã từng làm V: / • Thể た： / V ます → V て → V た', 1, 1, TRUE, 1),
(94, 19, 'Liệt kê hành động:', 'Liệt kê hành động:', 'Liệt kê hành động:', 'Cách dùng: Ø Dùng khi muốn biểu hiện một vài hành động đại diện trong số nhiều hành động mà chủ thể thực hiện, không cần quan tâm cái nào xảy ra trước cái nào xảy ra sau. Ø Thì của mẫu câu được thể hiện ở cuối câu.', 'V1 たり、V2 たり します。 / 日曜日 / にちようび', 1, 2, TRUE, 1),
(95, 19, 'Trở nên, trở thành:', 'A い → く / N に', 'Trở nên, trở thành:', 'Cách dùng: Chỉ sự thay đổi một tình trạng hay một điều kiện. sáng → tối, gầy → béo, to → nhỏ.', 'A い → く / A な → に なります／なりました。 / N に', 1, 3, TRUE, 1),
(96, 20, 'Thể thông thường và thể lịch sự:', 'THỂ THÔNG THƯỜNG / V ます', 'Thể thông thường và thể lịch sự:', 'Mỗi ngày tôi thức dậy lúc 6 giờ. • Dạng câu hỏi của động từ： cuối câu. Khi trả lời ở dạng câu hỏi có hoặc không:', 'THỂ THÔNG THƯỜNG / V ます / V る', 1, 1, TRUE, 1),
(97, 20, 'けど：nhưng Cách dùng:', 'けど：nhưng', 'けど：nhưng Cách dùng:', 'Cách dùng: Ø Hay được dùng trong hội thoại.', 'けど：nhưng / Ø けど có chức năng giống が。 / Tiếng Nhật khó nhưng mà thú vị.', 1, 2, TRUE, 1),
(98, 21, 'Tôi nghĩ là:', 'Tôi nghĩ là:', 'Tôi nghĩ là:', 'Cách dùng: Ø Biểu thị phỏng đoán, phán đoán chủ quan. Ø Bày tỏ ý kiến, đánh giá cá nhân. Ø Thể hiện sự đồng tình hoặc không đồng tình với ý kiến của người khác.', 'Thể thông thường とおもいます。', 1, 1, TRUE, 1),
(99, 21, 'Trích dẫn lời nói:', 'Trích dẫn lời nói:', 'Trích dẫn lời nói:', '• Trích dẫn lời nói của người khác. Ø Trích dẫn lời nói trực tiếp:', '1. TÔI NGHĨ LÀ. / 2. TRÍCH DẪN LỜI NÓI. / 3. ～PHẢI KHÔNG NHỈ?/ ～ĐÚNG KHÔNG?', 1, 2, TRUE, 1),
(100, 21, '～Phải không nhỉ?/ ～đúng không?', 'Ａな/Ｎだ→Ｎ', '～Phải không nhỉ?/ ～đúng không?', 'Cách dùng: Ø Kêu gọi sự đồng tình, xác nhận sự đồng ý của người nghe. Ø Phát âm lên cao giọng ở cuối câu.', 'Thể thông thường でしょう。 / Ａな/Ｎだ→Ｎ / かれは ハンサムでしょう。', 1, 3, TRUE, 1),
(101, 21, 'Ở đâu có điều gì đó:', 'Ở đâu có điều gì đó:', 'Ở đâu có điều gì đó:', 'Ở Hà Nội có trận bóng đá giữa Việt Nam và Thái Lan. • 1 sự việc diễn ra ở 1 tình huống nào đó:', 'Địa điểm で N が あります。 / ハノイで タイと ベトナムのサッカーの / しあいが あります。', 1, 4, TRUE, 1),
(102, 22, 'Mệnh đề bổ ngữ:', 'Mệnh đề bổ ngữ:', 'Mệnh đề bổ ngữ:', 'Định nghĩa: Ø Bổ ngữ là thành phần bổ sung thêm ý nghĩa, làm rõ nghĩa hơn cho danh từ. Ø Phần bổ ngữ luôn đứng trước danh từ mà nó bổ nghĩa. • Mệnh đề bổ nghĩa đã học: Ø Danh từ bổ nghĩa cho danh từ', 'Giáo viên tiếng Nhật. / 1. MỆNH ĐỀ BỔ NGỮ. / 2. MỆNH ĐỀ BỔ NGỮ CHO DANH TỪ LÀ VỊ NGỮ.', 1, 1, TRUE, 1),
(103, 22, 'Mệnh đề bổ ngữ cho danh từ là vị ngữ:', '=> trợ từ が. / Ø Chủ ngữ chính của câu => trợ từ は.', 'Mệnh đề bổ ngữ cho danh từ là vị ngữ:', 'Ý nghĩa: S là N mà. Lưu ý: Ø Chủ ngữ của mệnh đề bổ nghĩa cho danh từ => chủ ngữ phụ nguyên.', 'S は 文(thể thông thường) N です。 / => trợ từ が. / Ø Chủ ngữ chính của câu => trợ từ は.', 1, 2, TRUE, 1),
(104, 22, 'Mệnh đề bổ ngữ cho danh từ là chủ ngữ:', 'もの ひと ところ', 'Mệnh đề bổ ngữ cho danh từ là chủ ngữ:', 'Ý nghĩa: N mà… là…', '文(thể thông thường) N は ～ です。 / もの ひと ところ / めがねを かけている 人 はマイさんです。', 1, 3, TRUE, 1),
(105, 22, 'Mệnh đề bổ ngữ cho danh từ là chủ ngữ và vị ngữ:', '文(thể thông thường)N は 文(thể thông thường)N です. / S N', 'Mệnh đề bổ ngữ cho danh từ là chủ ngữ và vị ngữ:', 'Đôi giày mà tôi đang đi là đôi giày mà mẹ tôi đã mua.', '文(thể thông thường)N は 文(thể thông thường)N です. / S N', 1, 4, TRUE, 1),
(106, 22, 'Mệnh đề bổ ngữ cho danh từ là tân ngữ:', 'Mệnh đề bổ ngữ cho danh từ là tân ngữ:', 'Mệnh đề bổ ngữ cho danh từ là tân ngữ:', 'Tôi thích người mà có tính hài hước.', 'S は 文(thể thông thường)N+ を～。 / O が～。 / ユーモアが あるひと がすきです。', 1, 5, TRUE, 1),
(107, 22, 'Có (không có) thời gian, cuộc hẹn, việc bận, tiền để làm gì đó:', 'V る ＋ じかん／やくそく ＋ が あります', 'Có (không có) thời gian, cuộc hẹn, việc bận, tiền để làm gì đó:', 'Tôi không có thời gian để ăn trưa.', 'V る ＋ じかん／やくそく ＋ が あります / thể thông ようじ／おかね ありません。', 1, 6, TRUE, 1),
(108, 22, 'Chúng ta hãy cùng ～', 'Chúng ta hãy cùng ～', 'Chúng ta hãy cùng ～', 'Cách dùng: Ø Biểu thị đề nghị cả người nói và người nghe cùng làm một việc gì đó.', 'V ます → ましょうか。', 1, 7, TRUE, 1),
(109, 23, 'Khi/ lúc (trạng ngữ chỉ thời gian):', 'V る/ V ない / A い/ A な ＋とき', 'Khi/ lúc (trạng ngữ chỉ thời gian):', 'Chú ý: Ø Thời của mệnh đề bổ ngữ KHÔNG phụ thuộc vào thời của mệnh đề chính.', 'V る/ V ない / A い/ A な ＋とき / N の', 1, 1, TRUE, 1),
(110, 23, 'Trước khi/ sau khi:', 'V る / ＋とき', 'Trước khi/ sau khi:', 'Trước khi/ sau khi: Lưu ý: VD:', 'V る / 1. KHI/ LÚC (TRẠNG NGỮ CHỈ THỜI GIAN). / 3. HỄ/ CỨ LÀM V1 THÌ V2 TỰ DIỄN RA.', 1, 2, TRUE, 1),
(111, 23, 'Hễ/ cứ làm V1 thì V2 tự diễn ra:', 'Hễ/ cứ làm V1 thì V2 tự diễn ra:', 'Hễ/ cứ làm V1 thì V2 tự diễn ra:', 'Cách dùng: Ø Diễn tả một sự việc hiển nhiên, tự nhiên. Ø Dùng để hướng dẫn cách sử dụng máy móc, thiết bị. Ø Dùng để chỉ đường.', 'V１ると、 V２。 / はるになると、はなが さきます。 / V1 て、V2 て、V3 と、địa điểm にN があります。', 1, 3, TRUE, 1),
(112, 24, 'Cho, tặng hành động:', 'わたし', 'Cho, tặng hành động:', 'Ý nghĩa: A làm V cho B', 'A は B に N を V てあげます。 / わたし / わたしは おとうとに とけいを なおしてあげました。', 1, 1, TRUE, 1),
(113, 24, 'Nhận hành động:', 'Nhận hành động:', 'Nhận hành động:', 'Ý nghĩa: A được B làm V cho.', 'Nhận hành động: / A は B に N を V てもらいます。 / わたしは むすこに えを かいてもらいました。', 1, 2, TRUE, 1),
(114, 24, 'Cho, tặng (tôi):', 'Ø B thường là: 私 / わたし', 'Cho, tặng (tôi):', 'Cách dùng: Ø Ai đó cho, tặng mình (người thân) cái gì đó.', 'A は B に N を くれます。 / Ø B thường là: 私 / わたし', 1, 3, TRUE, 1),
(115, 24, 'Cho, tặng (tôi) hành động:', 'Cho, tặng (tôi) hành động:', 'Cho, tặng (tôi) hành động:', 'Ý nghĩa: A làm V cho B(tôi).', 'A は B に N を V てくれます。 / むすこは えを かいてくれました。', 1, 4, TRUE, 1),
(116, 24, 'Nhấn mạnh danh từ:', 'Nhấn mạnh danh từ:', 'Nhấn mạnh danh từ:', 'Mẹ đã nấu món ăn này cho tôi. Món ăn này là mẹ nấu cho tôi.', '5. Nhấn mạnh danh từ: / S は N を V ます。 / N は S が V ます。', 1, 5, TRUE, 1),
(117, 25, 'Câu điều kiện giả đinh: nếu…thì…:', 'A い → A かった / A な → A だった', 'Câu điều kiện giả đinh: nếu…thì…:', 'Cách dùng: Ø Dùng khi người nói muốn bày tỏ lập trường, ý kiến, mong muốn, yêu cầu, lời mời…của mình trong điều kiện giả định đó. của người nói.', 'A い → A かった / A な → A だった / （もし） N → N だった ら', 1, 1, TRUE, 1),
(118, 25, 'Sau khi làm V1 thì làm V2:', 'V1 たら、V2 / Ø Nhấn mạnh thứ tự trước sau của hành động.', 'Sau khi làm V1 thì làm V2:', 'Cách dùng: Ø Nhấn mạnh thứ tự trước sau của hành động. Ø V2 (mệnh đề chính) luôn ở thời hiện tại.', 'V1 たら、V2 / Ø Nhấn mạnh thứ tự trước sau của hành động. / (= V1 てから、V2)', 1, 2, TRUE, 1),
(119, 25, 'Câu mệnh đề ngược nghĩa: dù, cho dù… thì vẫn…:', 'A い → A くて / A な → A で', 'Câu mệnh đề ngược nghĩa: dù, cho dù… thì vẫn…:', 'Cách dùng: Ø Mệnh đề ngược nghĩa: Vế 1 có xảy ra như thế nào thì vế 2 vẫn sẽ xảy ra. Nhấn mạnh về mức độ điều kiện.', 'A い → A くて / A な → A で / （いくら）N → N で も', 1, 3, TRUE, 1)
